~~~csharp
public sealed class OutboxRelay(IServiceScopeFactory scopes, IProducer<string, string> producer, ILogger<OutboxRelay> log) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken ct)
    {
        var delay = TimeSpan.FromMilliseconds(250);
        while (!ct.IsCancellationRequested)
        {
            var published = await PublishBatchAsync(500, ct);
            if (published < 500) await Task.Delay(delay, ct);          // full batch: go again immediately
        }
    }

    private async Task<int> PublishBatchAsync(int size, CancellationToken ct)
    {
        await using var scope = scopes.CreateAsyncScope();
        var db = scope.ServiceProvider.GetRequiredService<PaymentsDbContext>();
        await using var tx = await db.Database.BeginTransactionAsync(ct);
        var batch = await db.Outbox.FromSql(
            $"SELECT TOP ({size}) * FROM dbo.Outbox WITH (UPDLOCK, READPAST, ROWLOCK) WHERE PublishedAt IS NULL ORDER BY Sequence")
            .ToListAsync(ct);

        var blocked = new HashSet<string>();                            // aggregates with a failure in this batch
        foreach (var m in batch)
        {
            if (blocked.Contains(m.AggregateId)) continue;              // keep per-aggregate order
            try
            {
                await producer.ProduceAsync(Topics.For(m.AggregateType), m.ToKafkaMessage(), ct);
                m.PublishedAt = DateTime.UtcNow;
            }
            catch (ProduceException<string, string> ex)
            {
                m.Attempts++; m.LastError = ex.Error.Reason; blocked.Add(m.AggregateId);
                log.LogWarning(ex, "Publish failed {MessageId} attempt {Attempt}", m.Id, m.Attempts);
            }
        }
        await db.SaveChangesAsync(ct);
        await tx.CommitAsync(ct);
        return batch.Count;
    }
}
