// Consumer guard: apply strictly in aggregate-version order
public async Task ApplyAsync(OrderEventEnvelope e, CancellationToken ct)
{
    var view = await db.OrderViews.FindAsync([e.OrderId], ct) ?? new OrderView { OrderId = e.OrderId, Version = 0 };

    if (e.Version <= view.Version) return;                       // duplicate or stale
    if (e.Version > view.Version + 1)                            // gap: earlier event not yet seen
    {
        await parking.ParkAsync(e, reason: $"gap {view.Version} to {e.Version}", ct);
        return;
    }

    view.Apply(e);                                               // Created, Paid, Cancelled
    view.Version = e.Version;
    db.Update(view);
    await db.SaveChangesAsync(ct);
    await parking.ReleaseNextAsync(e.OrderId, view.Version, ct);  // drain parked successors
}
