public sealed class PayoutDispatcher(PayoutsDbContext db, HttpClient provider, ILogger<PayoutDispatcher> log)
{
    public async Task DispatchAsync(OutboundCall call, CancellationToken ct)
    {
        using var req = new HttpRequestMessage(HttpMethod.Post, "/v1/payouts") { Content = JsonContent.Create(call.Body) };
        req.Headers.Add("Idempotency-Key", call.IdempotencyKey);         // "payout-{payoutId}", same on every retry
        try
        {
            using var res = await provider.SendAsync(req, ct);
            if (res.IsSuccessStatusCode)
                call.Succeed((await res.Content.ReadFromJsonAsync<ProviderPayout>(ct))!.Id);
            else if ((int)res.StatusCode is >= 400 and < 500 and not 409 and not 429)
                call.Reject(await res.Content.ReadAsStringAsync(ct));
            else
                call.MarkUnknown($"HTTP {(int)res.StatusCode}");          // retry later with the same key
        }
        catch (Exception ex) when (ex is HttpRequestException or TaskCanceledException)
        {
            call.MarkUnknown(ex.Message);                                  // never assume failure
        }
        await db.SaveChangesAsync(ct);
    }
}
