// Module integration via outbox + in-process relay
public sealed class InProcessOutboxRelay(IServiceScopeFactory scopes) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await using var scope = scopes.CreateAsyncScope();
            var db = scope.ServiceProvider.GetRequiredService<ModulesOutboxDbContext>();
            var batch = await db.Outbox.Where(o => o.PublishedAt == null).OrderBy(o => o.Sequence).Take(200).ToListAsync(ct);

            foreach (var m in batch)
            {
                var evt = IntegrationEvents.Deserialize(m.EventType, m.Payload);
                foreach (var handler in scope.ServiceProvider.GetServices<IIntegrationEventHandler>().Where(h => h.Handles(evt)))
                    await handler.HandleAsync(evt, m.Id, ct);     // each module's handler uses its own inbox
                m.PublishedAt = DateTime.UtcNow;
            }
            await db.SaveChangesAsync(ct);
            if (batch.Count == 0) await Task.Delay(200, ct);
        }
    }
}
