public sealed class SettlementToLedgerRecon(IPaymentsReadModel payments, ILedgerReadModel ledger, IBreakStore breaks, IRepublisher republisher)
{
    public async Task RunAsync(DateOnly businessDate, CancellationToken ct)
    {
        var settled = await payments.SettledOnAsync(businessDate, ct);          // id, amount, currency
        var posted  = await ledger.SettlementPostingsOnAsync(businessDate, ct);

        foreach (var missing in settled.ExceptBy(posted.Select(p => p.PaymentId), s => s.PaymentId))
        {
            var b = await breaks.OpenAsync(BreakType.MissingPosting, missing.PaymentId, missing.Amount, ct);
            if (await republisher.CanRepublishAsync(missing.PaymentId, ct))
                await republisher.RepublishAsync(missing.PaymentId, reason: b.Id, ct);   // same message id, consumers dedupe
        }

        foreach (var g in settled.GroupBy(s => s.Currency))
        {
            var src = g.Sum(s => s.Amount);
            var dst = posted.Where(p => p.Currency == g.Key).Sum(p => p.Amount);
            if (src != dst) await breaks.OpenAsync(BreakType.ValueMismatch, g.Key, src - dst, ct);
        }
    }
}
