public sealed record OutboxCapacity(double PeakPerSec, double AvgPerSec, int RowBytes, TimeSpan Outage, TimeSpan Retention)
{
    const double IndexOverhead = 1.4;
    public double OutageBufferGb => PeakPerSec * Outage.TotalSeconds * RowBytes * IndexOverhead / 1e9;
    public double SteadyGb       => AvgPerSec * Retention.TotalSeconds * RowBytes * IndexOverhead / 1e9;
    public double ExtraWriteMbPerSec(bool polling) => PeakPerSec * RowBytes * IndexOverhead * (polling ? 2 : 1) / 1e6;
}

